from openpyxl import load_workbook
from pathlib import Path
src=Path('/root/data/workbook.xlsx')
out=Path('/root/output/result.xlsx')
out.parent.mkdir(parents=True, exist_ok=True)
wb=load_workbook(src, data_only=False)
ws=wb['Task']
# Step 1 lookup formulas: Data headers are row 4, year values H:L; series codes in D21:D38; values H21:L38.
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=ws.cell(1,c).column_letter
            ws.cell(r,c).value = f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'

# Step 2 net production slack rows 35-40: (Finished Output rows 12-17 - Scrap rows 19-24) / Rated Capacity rows 26-31 * 100.
for i,r in enumerate(range(35,41)):
    fin=12+i
    scrap=19+i
    cap=26+i
    for c in range(8,13):
        col=ws.cell(1,c).column_letter
        ws.cell(r,c).value = f'=({col}{fin}-{col}{scrap})/{col}{cap}*100'

# Step 2 statistics rows 42-47 according to labels in E42:E47.
for r in range(42,48):
    label = str(ws.cell(r,5).value or '').strip().lower()
    for c in range(8,13):
        col=ws.cell(1,c).column_letter
        rng=f'{col}$35:{col}$40'
        if 'minimum' in label or label == 'min':
            formula=f'=MIN({rng})'
        elif 'maximum' in label or label == 'max':
            formula=f'=MAX({rng})'
        elif 'median' in label:
            formula=f'=MEDIAN({rng})'
        elif 'mean' in label or 'average' in label:
            formula=f'=AVERAGE({rng})'
        elif '25' in label or 'first quartile' in label or 'lower quartile' in label:
            formula=f'=PERCENTILE.INC({rng},0.25)'
        elif '75' in label or 'third quartile' in label or 'upper quartile' in label:
            formula=f'=PERCENTILE.INC({rng},0.75)'
        else:
            raise ValueError(f'Unrecognized statistic label at row {r}: {ws.cell(r,5).value!r}')
        ws.cell(r,c).value = formula

# Step 3 weighted mean rows H50:L50, weights are Rated Production Capacity rows 26-31.
for c in range(8,13):
    col=ws.cell(1,c).column_letter
    ws.cell(50,c).value = f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'

wb.save(out)
print(f'Saved {out}')
print('Formula blocks written: H12:L17, H19:L24, H26:L31, H35:L40, H42:L47, H50:L50')
